"""Generated by solo-to-scale; edit `templates/tools/build_dashboard.py` in the plugin, then run upgrade.

The startup dashboard: one page with tabs (Overview, Goals, Documents, Progress trace, Roadmap, Scope and
journey, Team and board, Agent activity, Decisions, Approvals inbox, Costs), built from the repo and GitHub.
The dashboard workflow rebuilds it on every merge to main and every hour, and serves it at the host in
founder/dashboard.json behind a Cloudflare Access login. The Claude page from publish-views is the backup.

  python tools/build_dashboard.py build [--out DIR] [--offline] [--summary FILE]
                                       # DIR/index.html (default .dashboard/); FILE: the portfolio summary
  python tools/build_dashboard.py guard [--github-output FILE]    # may this build be deployed? (CI)
  python tools/build_dashboard.py verify                          # after a deploy: is it behind the login? (CI)

`build` never fails because GitHub is unreachable: the repo tabs are still built and the page says which
GitHub data is missing. `guard` fails closed: it allows a deploy only when founder/dashboard.json names a
host and a Pages project, the Cloudflare secrets are set, and a Cloudflare Access application with a login
policy (not `everyone`, not `bypass`) covers both the host and <project>.pages.dev. It exits 0 with
deploy=no when hosting isn't set up, and 1 when it is set up but the login isn't. `verify` exits 1 if an
anonymous visitor gets the dashboard. Every text on the page is shown as text, never as HTML.
`--summary` also writes the small, document-free summary that a portfolio reads (tools/build_portfolio.py);
the dashboard workflow uploads it as the `dashboard-data` workflow artifact.
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import html
import json
import os
import re
import subprocess
import sys
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import build_roadmap  # noqa: E402
import build_team  # noqa: E402
import build_traceability  # noqa: E402
import doctor  # noqa: E402
import goals  # noqa: E402
import heartbeat  # noqa: E402
import tickets  # noqa: E402

PAGE = Path(__file__).resolve().parent / "dashboard.html"
MARKER = 'name="s2s-dashboard"'
DOC_LIMIT = 200_000
DEFAULT_DOCS = ["founder/business-context.md", "founder/brand.md", "founder/status.md",
                "founder/operating-protocol.md", "founder/sources/*.md"]
# Product and technical documents are always looked for, on top of founder/dashboard.json's list.
PRODUCT_DOCS = ["specs/*/spec.md", "specs/*/ux/*.md", "docs/product/**/*.md"]
TECHNICAL_DOCS = ["specs/*/plan.md", "specs/*/research.md", "specs/*/data-model.md", "specs/*/quickstart.md",
                  "specs/*/contracts/*.md", "specs/*/tasks.md", ".specify/memory/constitution.md", "docs/**/*.md"]
DOC_COUNT_LIMIT = 150
HOST = re.compile(r"^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$")
PAGES_PROJECT = re.compile(r"^[a-z0-9]([a-z0-9-]{0,56}[a-z0-9])?$")
CF_API = "https://api.cloudflare.com/client/v4"
SUMMARY_SCHEMA = 1


def settings(root: Path) -> dict[str, Any]:
    try:
        data = json.loads(s.read(root / "founder" / "dashboard.json") or "{}")
    except ValueError:
        data = {}
    return data if isinstance(data, dict) else {}


# --- the repo half (always built) ------------------------------------------------------------------------

def title_of(text: str, rel: str) -> str:
    m = re.search(r"^#\s+(.+)$", text, re.M)
    return m.group(1).strip() if m else Path(rel).stem.replace("-", " ").capitalize()


def documents(root: Path, patterns: list[str]) -> list[dict[str, str]]:
    out, seen = [], set()
    base = root.resolve()
    for pattern in patterns:
        if not isinstance(pattern, str) or pattern.startswith(("/", "\\")) or ".." in pattern:
            continue
        for path in sorted(root.glob(pattern)):
            try:
                rel = path.resolve().relative_to(base).as_posix()
            except ValueError:
                continue  # a link out of the repo
            if rel in seen or not path.is_file() or path.name == "README.md" and "sources" in path.parts:
                continue
            seen.add(rel)
            text = s.read(path)
            if len(text) > DOC_LIMIT:
                text = text[:DOC_LIMIT] + "\n\n(cut here: the rest is in the repo)"
            out.append({"path": rel, "title": title_of(text, rel), "text": text})
    return out


def group_of(rel: str) -> str:
    """business, product or technical: where a document sits in the journey."""
    parts = rel.split("/")
    if parts[0] == "specs" and len(parts) > 2:
        return "product" if parts[2] in ("spec.md", "ux") else "technical"
    if parts[0] == "docs":
        return "product" if len(parts) > 2 and parts[1] == "product" else "technical"
    if parts[0] == ".specify":
        return "technical"
    return "business"


def grouped_documents(root: Path, patterns: list[str]) -> list[dict[str, str]]:
    """The founder's list plus the product and technical documents, each with its group, feature and last change."""
    docs = documents(root, list(patterns) + PRODUCT_DOCS + TECHNICAL_DOCS)[:DOC_COUNT_LIMIT]
    for d in docs:
        d["group"] = group_of(d["path"])
        parts = d["path"].split("/")
        d["feature"] = parts[1] if parts[0] == "specs" and len(parts) > 2 else ""
        d["updated"] = (s.git(root, "log", "-1", "--format=%cI", "--", d["path"]) or "").strip()
    return docs


def repo_data(root: Path, cfg_dash: dict[str, Any]) -> dict[str, Any]:
    cfg = s.config(root)
    pol = heartbeat.policy(root)
    slices = s.slices(root, cfg)
    roles = s.epic_roles(root)
    epics = []
    for code, ep in sorted(slices["epics"].items()):
        stories = [st for st in slices["stories"] if st.get("epic") == code]
        epics.append({"code": code, "name": (ep or {}).get("name", code), "goal": (ep or {}).get("goal", ""),
                      "role": roles.get(code, "engineer"), "stories": len(stories),
                      "slices": sorted({str(st.get("slice", "")) for st in stories if st.get("slice")})})
    memos = [d for d in documents(root, ["founder/board/*.md"]) if not d["path"].endswith("README.md")]
    beats = {r: {k: ((pol.get("roles") or {}).get(r) or {}).get(k) for k in ("enabled", "cron", "monthly_budget_usd")}
             for r in heartbeat.BUDGET_ROLES}
    return {
        "goals": goals.build(root),
        "documents": grouped_documents(root, cfg_dash.get("documents") or DEFAULT_DOCS),
        "roadmap": build_roadmap.build(root),
        "trace": build_traceability.build(root),
        "team": build_team.build(root),
        "team_doc": s.read(root / "founder" / "team.md")[:DOC_LIMIT],
        "heartbeats": beats,
        "memos": memos,
        "epics": epics,
        "decisions": s.decisions(root, cfg),
        "approved_words": cfg.get("approved_words") or ["Approved"],
    }


# --- the GitHub half (best effort) -----------------------------------------------------------------------

def all_comments(hub: tickets.Hub, n: int, pages: int = 20) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for page in range(1, pages + 1):
        got = hub.api(f"issues/{n}/comments?per_page=100&page={page}") or []
        out += got
        if len(got) < 100:
            break
    return out


def approvals(hub: tickets.Hub, root: Path) -> list[dict[str, Any]]:
    pol = approval.policy(root)
    who = approval.founders(pol, hub.repo)
    open_ = hub.tickets("open", approval.LABEL)
    closed = sorted(hub.tickets("closed", approval.LABEL), key=lambda i: -i["number"])[:15]
    out = []
    for issue in [*open_, *closed]:
        d = approval.decide(hub.api(f"issues/{issue['number']}/comments?per_page=100") or [], who)
        gate = next((lb[5:] for lb in tickets.labels_of(issue) if lb.startswith("gate:")), "")
        body = issue.get("body") or ""
        scope = (re.search(r"\*\*Scope:\*\* (.*)", body) or [None, ""])[1].strip()
        by = (re.search(r"\*\*Requested by:\*\* (.*)", body) or [None, ""])[1].strip()
        out.append({"number": issue["number"], "title": issue.get("title", ""), "url": issue.get("html_url", ""),
                    "gate": gate, "state": d["state"], "kind": d["kind"], "note": d["note"], "scope": scope,
                    "by": by, "open": issue.get("state") == "open", "created": issue.get("created_at", "")})
    return out


def costs(hub: tickets.Hub, root: Path, month: str) -> dict[str, Any]:
    pol = heartbeat.policy(root)
    c = heartbeat.Costs(hub, month)
    comments = c.comments()
    totals = heartbeat.spent(comments, month)
    entries = []
    for cm in comments:
        m = heartbeat.MARK.search(cm.get("body") or "")
        try:
            data = json.loads(m.group(1)) if m else None
        except ValueError:
            data = None
        if isinstance(data, dict) and data.get("month") == month:
            entries.append({**data, "at": cm.get("created_at", "")})
    roles = []
    for role in heartbeat.BUDGET_ROLES:
        cap, used, base = heartbeat.standing(hub, root, pol, role, month, totals) if pol.get("roles") else (None, totals.get(role, 0.0), 0.0)
        roles.append({"role": role, "used": round(used, 4), "cap": cap, "base": base or None})
    return {"month": month, "roles": roles, "entries": entries[-100:], "total": round(sum(totals.values()), 4)}


def github_data(root: Path, cfg_dash: dict[str, Any], month: str) -> dict[str, Any]:
    repo = approval.repo_name(root)
    if not repo:
        return {"ok": False, "why": "can't tell which GitHub repo this is"}
    hub = tickets.Hub(repo)
    limit = int(cfg_dash.get("activity_limit") or 200)
    try:
        logs = hub.tickets("all", tickets.LOG)
        activity = tickets.parse_log(all_comments(hub, logs[0]["number"])) if logs else []
        open_tickets = [{"number": t["number"], "title": t.get("title", ""), "url": t.get("html_url", ""),
                         "role": tickets.role_of(t), "claimed": tickets.CLAIMED in tickets.labels_of(t),
                         "blocked": tickets.BLOCKED in tickets.labels_of(t),
                         "goal": goals.objective_of(tickets.labels_of(t))} for t in hub.tickets("open")]
        pulls = hub.api("pulls?state=closed&sort=updated&direction=desc&per_page=20") or []
        merged = [{"number": p["number"], "title": p.get("title", ""), "url": p.get("html_url", ""),
                   "by": (p.get("user") or {}).get("login", ""), "merged": p.get("merged_at", "")}
                  for p in pulls if p.get("merged_at")]
        return {"ok": True, "repo": repo, "activity": activity[-limit:], "tickets": open_tickets,
                "approvals": approvals(hub, root), "costs": costs(hub, root, month), "merged": merged}
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        return {"ok": False, "repo": repo, "why": f"GitHub unavailable or unexpected reply ({type(exc).__name__})"}


# --- the page --------------------------------------------------------------------------------------------

def embed(data: Any) -> str:
    """JSON that is safe inside a <script> element, whatever the text in it says."""
    text = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    for ch, esc in (("<", "\\u003c"), (">", "\\u003e"), ("&", "\\u0026"), (" ", "\\u2028"), (" ", "\\u2029")):
        text = text.replace(ch, esc)
    return text


def https_url(url: Any) -> str:
    """An https address safe to put in a link, or ''."""
    url = str(url or "").strip()
    return url if re.fullmatch(r"https://[^\s\"'<>]+", url) else ""


def setup(root: Path, offline: bool, now: dt.datetime) -> list[dict[str, str]]:
    """The doctor's findings for the Setup card; never stops the build."""
    try:
        return doctor.run(root, offline=offline, now=now)
    except Exception as exc:  # noqa: BLE001 - the page still builds
        return [doctor.item("doctor", "Setup check", "unknown", f"the check itself failed ({type(exc).__name__})")]


def build(root: Path, offline: bool = False, now: dt.datetime | None = None) -> dict[str, Any]:
    now = now or dt.datetime.now(dt.timezone.utc)
    cfg_dash = settings(root)
    proj = s.project(root)
    head = (s.git(root, "log", "-1", "--format=%h%n%cI") or "").split("\n")
    month = now.strftime("%Y-%m")
    return {
        "project": {"name": proj.get("name", ""), "one_line": proj.get("one_line", ""), "repo": proj.get("repo", ""),
                    "stage": proj.get("stage")},
        "commit": head[0] if head and head[0] else "", "commit_date": head[1] if len(head) > 1 else "",
        "built": now.strftime("%Y-%m-%dT%H:%M:%SZ"), "month": month,
        "links": {"portfolio": https_url(cfg_dash.get("portfolio_url")),
                  "portfolio_name": " ".join(str(cfg_dash.get("portfolio_name") or "").split())[:80]},
        "repo": repo_data(root, cfg_dash),
        "setup": setup(root, offline, now),
        "github": {"ok": False, "why": "built offline"} if offline else github_data(root, cfg_dash, month),
    }


def page(data: dict[str, Any]) -> str:
    name = data["project"]["name"] or "Startup"
    before, _, after = s.read(PAGE).partition("__S2S_DATA__")
    return before.replace("__S2S_TITLE__", html.escape(f"{name} dashboard")) + embed(data) + after


def clip(text: Any, n: int = 300) -> str:
    text = str(text or "")
    return text if len(text) <= n else text[: n - 1] + "…"


def goal_summary(g: dict[str, Any]) -> dict[str, Any]:
    """The goal and each active objective's progress: titles and numbers, never the reasons or history."""
    objs = [o for o in g.get("objectives") or [] if o.get("status") == "active"]
    return {"goal": clip(g.get("goal"), 200),
            "objectives": [{"id": o.get("id"), "title": clip(o.get("title"), 120), "quarter": o.get("quarter", ""),
                            "progress": o.get("progress")} for o in objs][:6]}


def summary(data: dict[str, Any]) -> dict[str, Any]:
    """What a portfolio shows for this venture: counts and short lists, never the business documents."""
    repo, gh_ = data.get("repo") or {}, data.get("github") or {}
    road = repo.get("roadmap") or {}
    stages, slices = road.get("stages") or [], road.get("slices") or []
    cur = next((x for x in stages if x.get("stage") == road.get("current_stage")), {})
    building = [x for x in slices if re.search(r"progress|building", str(x.get("status")), re.I)]
    out: dict[str, Any] = {
        "schema": SUMMARY_SCHEMA, "project": data.get("project") or {}, "commit": data.get("commit", ""),
        "built": data.get("built", ""), "month": data.get("month", ""),
        "stage": {"number": road.get("current_stage"), "phase": cur.get("phase", ""), "name": cur.get("name", "")},
        "slices": {"total": len(slices), "done": sum(str(x.get("status")).lower() == "done" for x in slices),
                   "building": [clip(f"{x.get('id')}: {x.get('name')}", 120) for x in building][:3]},
        "trace": [{k: c.get(k) for k in ("level", "done", "total", "pct")} for c in (repo.get("trace") or {}).get("chain") or []],
        "blockers": [{"item": clip(b.get("item"), 200), "needed_by": b.get("needed_by", "")} for b in road.get("blockers") or []][:10],
        "decisions_waiting": [{"id": d.get("id"), "decision": clip(d.get("decision"), 200), "status": d.get("status"),
                               "date": d.get("date", "")} for d in road.get("decisions_waiting") or []][:10],
        "goals": goal_summary(repo.get("goals") or {}),
        "github": {"ok": bool(gh_.get("ok")), "why": gh_.get("why", "")},
    }
    if gh_.get("ok"):
        open_t = gh_.get("tickets") or []
        roles = (gh_.get("costs") or {}).get("roles") or []
        out["github"].update({
            "approvals_waiting": [{k: a.get(k) for k in ("number", "title", "url", "gate", "by", "created")}
                                  for a in gh_.get("approvals") or [] if a.get("open") and a.get("state") == "waiting"][:20],
            "tickets": {"open": len(open_t), "claimed": sum(bool(t.get("claimed")) for t in open_t),
                        "blocked": sum(bool(t.get("blocked")) for t in open_t)},
            "costs": {"total": (gh_.get("costs") or {}).get("total", 0),
                      "cap": round(sum(r.get("cap") or 0 for r in roles), 4),
                      "roles": [{k: r.get(k) for k in ("role", "used", "cap")} for r in roles if r.get("cap") or r.get("used")]},
            "activity": [{**{k: a.get(k) for k in ("role", "action", "ticket", "to", "at")}, "why": clip(a.get("why"))}
                         for a in (gh_.get("activity") or [])[-20:]],
            "merged": (gh_.get("merged") or [])[:5],
        })
    return out


def cmd_build(a: argparse.Namespace) -> int:
    data = build(a.root, a.offline)
    if a.summary:
        a.summary.parent.mkdir(parents=True, exist_ok=True)
        a.summary.write_text(json.dumps(summary(data), ensure_ascii=False, indent=1), encoding="utf-8", newline="\n")
    out = (a.out or a.root / ".dashboard")
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(page(data), encoding="utf-8", newline="\n")
    (out / "robots.txt").write_text("User-agent: *\nDisallow: /\n", encoding="utf-8", newline="\n")
    gh_ok = data["github"].get("ok")
    print(f"wrote {out / 'index.html'} at {data['commit'] or 'no commit'}; GitHub data: "
          + ("included" if gh_ok else f"missing ({data['github'].get('why')})"))
    return 0


# --- hosting: Cloudflare Pages behind Cloudflare Access ---------------------------------------------------

def http(url: str, headers: dict[str, str] | None = None) -> tuple[int, dict[str, str], str]:
    """One GET without following redirects: (status, headers, body). Raises OSError if unreachable."""
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args: Any, **kwargs: Any) -> None:
            return None
    req = urllib.request.Request(url, headers={"User-Agent": "solo-to-scale-dashboard", **(headers or {})})
    try:
        with urllib.request.build_opener(NoRedirect).open(req, timeout=20) as resp:
            return resp.status, dict(resp.headers), resp.read(400_000).decode("utf-8", "replace")
    except urllib.error.HTTPError as err:
        return err.code, dict(err.headers or {}), (err.read(400_000) or b"").decode("utf-8", "replace")


def covers(entry: str, host: str) -> bool:
    """Does one Access application domain entry protect the whole of `host`?"""
    entry = re.sub(r"^https?://", "", (entry or "").strip().lower())
    name, _, path = entry.partition("/")
    if path not in ("", "*"):
        return False  # protects only part of the site
    if name == host:
        return True
    return name.startswith("*.") and host.endswith(name[1:]) and host != name[2:]


def login_policy(app: dict[str, Any]) -> str:
    """'' if the app's policies require a login for specific people, else why not."""
    policies = app.get("policies")
    if not isinstance(policies, list) or not policies:
        return "has no policies"
    for p in policies:
        decision = str(p.get("decision") or "").lower()
        if decision in ("bypass", "non_identity"):
            return f"has a {decision} policy, which lets anyone in"
        if decision == "allow" and any("everyone" in (rule or {}) for rule in p.get("include") or []):
            return "allows everyone"
    if not any(str(p.get("decision") or "").lower() == "allow" for p in policies):
        return "has no allow policy"
    return ""


def access_apps(account: str, token: str) -> list[dict[str, Any]]:
    apps, page_no = [], 1
    while True:
        status, _, body = http(f"{CF_API}/accounts/{account}/access/apps?per_page=100&page={page_no}",
                               {"Authorization": f"Bearer {token}"})
        data = json.loads(body or "{}")
        if status != 200 or not data.get("success"):
            raise ValueError(f"Cloudflare API answered {status}")
        apps += data.get("result") or []
        info = data.get("result_info") or {}
        if page_no >= int(info.get("total_pages") or 1):
            return apps
        page_no += 1


def protection(apps: list[dict[str, Any]], host: str) -> str:
    """'' if a self-hosted Access app with a login policy covers host, else why not."""
    reasons = []
    for app in apps:
        entries = [app.get("domain") or "", *(app.get("self_hosted_domains") or []),
                   *((d or {}).get("uri", "") for d in app.get("destinations") or [] if (d or {}).get("type", "public") == "public")]
        if str(app.get("type") or "self_hosted") != "self_hosted" or not any(covers(e, host) for e in entries):
            continue
        why = login_policy(app)
        if not why:
            return ""
        reasons.append(f"Access app {app.get('name') or app.get('id')!r} {why}")
    return "; ".join(reasons) or "no Cloudflare Access application covers it"


def targets(cfg: dict[str, Any]) -> tuple[str, str]:
    host = str(cfg.get("host") or "").strip().lower()
    proj = str(cfg.get("cloudflare_pages_project") or "").strip().lower()
    return host, proj


def cmd_guard(a: argparse.Namespace) -> int:
    return guard(settings(a.root), a.github_output)


def guard(cfg: dict[str, Any], github_output: str, file: str = "founder/dashboard.json", what: str = "dashboard",
          section: str = "The startup dashboard") -> int:
    """Shared by the dashboard and the portfolio: deploy only behind a Cloudflare Access login."""
    def out(deploy: bool, project: str = "") -> None:
        if github_output:
            with open(github_output, "a", encoding="utf-8") as f:
                f.write(f"deploy={'yes' if deploy else 'no'}\nproject={project}\n")
    host, proj = targets(cfg)
    if not host and not proj:
        print(f"hosting not set up ({file} has no host): built only, not deployed")
        out(False)
        return 0
    if not HOST.match(host) or not PAGES_PROJECT.match(proj):
        print(f"{file}: host must be a domain like pm.example.com and cloudflare_pages_project a "
              "Pages project name (lower-case letters, digits, hyphens): not deployed")
        out(False)
        return 1
    token, account = os.environ.get("CLOUDFLARE_API_TOKEN", ""), os.environ.get("CLOUDFLARE_ACCOUNT_ID", "")
    if not token or not re.fullmatch(r"[0-9a-f]{32}", account):
        print("CLOUDFLARE_API_TOKEN or CLOUDFLARE_ACCOUNT_ID isn't set as a repository secret: built only, not deployed."
              f" The founder adds them (handbook: '{section}').")
        out(False)
        return 0
    try:
        apps = access_apps(account, token)
    except (OSError, ValueError, TypeError, AttributeError) as exc:
        print(f"can't read the Cloudflare Access applications ({exc}); the token needs Access: Apps and Policies"
              " Read: not deployed")
        out(False)
        return 1
    problems = [f"{h}: {why}" for h in (host, f"{proj}.pages.dev") if (why := protection(apps, h))]
    if problems:
        print(f"not deployed: the {what} must sit behind a login.\n  " + "\n  ".join(problems)
              + "\nAdd a self-hosted Cloudflare Access application covering both, with an allow policy for your"
                " own email addresses.")
        out(False)
        return 1
    print(f"{host} and {proj}.pages.dev are behind a Cloudflare Access login: deploy")
    out(True, proj)
    return 0


def exposed(url: str, marker: str = MARKER) -> str:
    """'' when an anonymous request doesn't get the page, 'unreachable' or 'EXPOSED' otherwise."""
    try:
        status, _, body = http(url)
    except OSError:
        return "unreachable"
    return "EXPOSED" if status == 200 and marker in body else ""


def cmd_verify(a: argparse.Namespace) -> int:
    return verify(settings(a.root))


def verify(cfg: dict[str, Any], marker: str = MARKER, what: str = "dashboard") -> int:
    host, proj = targets(cfg)
    if not HOST.match(host) or not PAGES_PROJECT.match(proj):
        print("hosting not set up: nothing to verify")
        return 0
    bad = 0
    for url in (f"https://{host}/", f"https://{proj}.pages.dev/"):
        state = exposed(url, marker)
        if state == "EXPOSED":
            bad = 1
            print(f"EXPOSED: {url} serves the {what} without a login. Turn on Cloudflare Access for it now.")
        elif state:
            print(f"{url}: unreachable (DNS or the custom domain may not be set up yet)")
        else:
            print(f"{url}: behind the login")
    return bad


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="The startup dashboard")
    sub = ap.add_subparsers(dest="cmd", required=True)
    b = sub.add_parser("build", parents=[common])
    b.add_argument("--out", type=Path)
    b.add_argument("--offline", action="store_true", help="skip GitHub")
    b.add_argument("--summary", type=Path, help="also write the portfolio summary here")
    sub.add_parser("guard", parents=[common]).add_argument("--github-output", default="")
    sub.add_parser("verify", parents=[common])
    a = ap.parse_args(argv)
    return {"build": cmd_build, "guard": cmd_guard, "verify": cmd_verify}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
